from collections import Counter


def transform(grid):
    """Complete prominent horizontal and vertical runs with color 2."""
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != background]
    if not points:
        return [row[:] for row in grid]

    r0 = min(r for r, _ in points)
    r1 = max(r for r, _ in points)
    c0 = min(c for _, c in points)
    c1 = max(c for _, c in points)
    row_counts = [sum(value != background for value in row) for row in grid]

    # The top and bottom occupied rows, and any row with at least four marks,
    # are completed across the full occupied width.
    horizontal_rows = {
        r for r in range(r0, r1 + 1)
        if r in (r0, r1) or row_counts[r] >= 4
    }
    out = [row[:] for row in grid]
    for r in horizontal_rows:
        for c in range(c0, c1 + 1):
            if out[r][c] == background:
                out[r][c] = 2

    # Extend columns with at least three marks if at least one mark lies outside
    # the completed horizontal rows.
    for c in range(c0, c1 + 1):
        rows = [r for r in range(h) if grid[r][c] != background]
        if len(rows) >= 3 and any(r not in horizontal_rows for r in rows):
            for r in range(r0, r1 + 1):
                if out[r][c] == background:
                    out[r][c] = 2
    return out
